 const flush=async()=>{finishGesture();navigationPending=false;for(const s of Object.values(stores)){try{await s.flush();}catch(e){const st=s.state||{},retryable=st.conflict||st.state==='offline'||e.retryable||e.status===409||e.status>=500||!e.status&&/network|fetch|offline|connection|timed out|failed to load/i.test(e.message||'');if(st.draftPreserved&&(retryable||e.code==='WHITEBOARD_ACCESS_CHANGED')){navigationPending=true;window.LZShell?.showMessage('Whiteboard changes are preserved on this computer and will retry when you reopen it.',false);}else throw e;}}};
